import { useState, useEffect, useRef, useMemo, FormEvent, ChangeEvent, CSSProperties } from 'react';
import {
  FormsSDKConfig,
  FormField,
  FormStyling,
  SecondaryButton,
  SubmissionResponse,
  ValidationError,
} from '../core';
import { useForm, UseFormOptions } from './use-form';

const defaultStyling: FormStyling = {
  theme: 'light',
  primaryColor: '#3b82f6',
  backgroundColor: '#ffffff',
  textColor: '#1f2937',
  borderRadius: 'md',
  fontSize: 'md',
  buttonStyle: 'filled',
  labelPosition: 'top',
};

function getBorderRadius(radius: FormStyling['borderRadius']): string {
  switch (radius) {
    case 'none': return '0';
    case 'sm': return '0.125rem';
    case 'md': return '0.375rem';
    case 'lg': return '0.5rem';
    default: return '0.375rem';
  }
}

function getFieldBorderRadius(radius?: FormStyling['fieldBorderRadius']): string {
  switch (radius) {
    case 'none': return '0';
    case 'small': return '0.25rem';
    case 'medium': return '0.375rem';
    case 'large': return '0.75rem';
    case 'full': return '9999px';
    default: return '0.375rem';
  }
}

function getWidthPercent(width?: string): string | undefined {
  switch (width) {
    case '1/4': return '25%';
    case '1/3': return '33.333%';
    case '1/2': return '50%';
    case '2/3': return '66.666%';
    case '3/4': return '75%';
    case 'full': return '100%';
    default: return undefined;
  }
}

type FieldRow = { type: 'single'; field: FormField } | { type: 'row'; fields: FormField[] };

function groupFieldsIntoRows(fields: FormField[]): FieldRow[] {
  const result: FieldRow[] = [];
  let i = 0;
  while (i < fields.length) {
    const field = fields[i];
    if (field.row != null) {
      const rowFields: FormField[] = [field];
      let j = i + 1;
      while (j < fields.length && fields[j].row === field.row) {
        rowFields.push(fields[j]);
        j++;
      }
      if (rowFields.length > 1) {
        result.push({ type: 'row', fields: rowFields });
      } else {
        result.push({ type: 'single', field });
      }
      i = j;
    } else {
      result.push({ type: 'single', field });
      i++;
    }
  }
  return result;
}

function getButtonRadius(radius?: FormStyling['buttonRadius']): string {
  switch (radius) {
    case 'none': return '0';
    case 'small': return '4px';
    case 'medium': return '8px';
    case 'large': return '12px';
    case 'full': return '9999px';
    default: return '8px';
  }
}

function getFontSize(size: FormStyling['fontSize']): string {
  switch (size) {
    case 'sm': case 'small': return '0.875rem';
    case 'md': case 'medium': return '1rem';
    case 'lg': case 'large': return '1.125rem';
    default: return '1rem';
  }
}

function getPlaceholderFontSize(size?: FormStyling['placeholderFontSize']): string {
  switch (size) {
    case 'small': return '0.75rem';
    case 'large': return '1rem';
    default: return '0.875rem';
  }
}

function getFieldSpacing(spacing?: FormStyling['fieldSpacing']): string {
  switch (spacing) {
    case 'compact': return '0.5rem';
    case 'relaxed': return '1.5rem';
    case 'spacious': return '2rem';
    default: return '1rem';
  }
}

function getFormPadding(padding?: FormStyling['formPadding']): string {
  switch (padding) {
    case 'none': return '0';
    case 'compact': return '1rem';
    case 'relaxed': return '2.5rem';
    case 'spacious': return '3.5rem';
    default: return '1.5rem';
  }
}

function getLabelSpacing(spacing?: FormStyling['labelSpacing']): string {
  switch (spacing) {
    case 'compact': return '0.125rem';
    case 'relaxed': return '0.75rem';
    default: return '0.25rem';
  }
}

function getFormMaxWidth(width?: FormStyling['formWidth']): string {
  switch (width) {
    case 'narrow': return '28rem';
    case 'wide': return '48rem';
    case 'full': return '100%';
    default: return '36rem';
  }
}

function getButtonAlign(align?: FormStyling['buttonAlign']): string {
  switch (align) {
    case 'left': return 'flex-start';
    case 'right': return 'flex-end';
    default: return 'center';
  }
}

function getHeadingSize(size?: FormStyling['headingSize']): string {
  switch (size) {
    case 'small': return '1.125rem';
    case 'large': return '1.875rem';
    case 'extra-large': return '2.25rem';
    default: return '1.5rem';
  }
}

function getParagraphSize(size?: FormStyling['paragraphSize']): string {
  switch (size) {
    case 'small': return '0.875rem';
    case 'large': return '1.125rem';
    default: return '1rem';
  }
}

interface FormsExpertFormProps {
  /** SDK configuration (optional if using FormsProvider) */
  config?: FormsSDKConfig;
  /** Form slug */
  slug: string;
  /** Track form views for analytics (completion rate). Default: true */
  trackViews?: boolean;
  /** Custom submit button text */
  submitText?: string;
  /** Success callback */
  onSuccess?: (response: SubmissionResponse) => void;
  /** Error callback */
  onError?: (error: Error) => void;
  /** Validation error callback */
  onValidationError?: (errors: ValidationError[]) => void;
  /** Custom class name */
  className?: string;
  /** Custom styles */
  style?: CSSProperties;
  /** Language code to pass to backend */
  lang?: string;
}

/**
 * Forms Expert form component
 */
export function FormsExpertForm({
  config,
  slug,
  trackViews = true,
  submitText = 'Submit',
  onSuccess,
  onError,
  onValidationError,
  className,
  style,
  lang,
}: FormsExpertFormProps) {
  const form = useForm({
    slug,
    config,
    trackViews,
    onSuccess,
    onError,
    onValidationError,
    autoInit: true,
    lang,
  });

  const [captchaToken, setCaptchaToken] = useState<string | null>(null);
  const captchaContainerRef = useRef<HTMLDivElement>(null);
  const captchaWidgetId = useRef<string | null>(null);
  const captchaScriptLoaded = useRef(false);
  const formScopeId = useMemo(() => 'fe-' + Math.random().toString(36).slice(2, 8), []);

  // Load captcha script and render widget
  useEffect(() => {
    if (!form.requiresCaptcha || !form.captchaSiteKey || !form.captchaProvider) return;
    if (captchaScriptLoaded.current) return;

    const provider = form.captchaProvider;
    const siteKey = form.captchaSiteKey;

    const renderWidget = () => {
      if (!captchaContainerRef.current) return;

      const w = window as any;
      if (provider === 'turnstile' && w.turnstile) {
        captchaWidgetId.current = w.turnstile.render(captchaContainerRef.current, {
          sitekey: siteKey,
          callback: (token: string) => setCaptchaToken(token),
          'expired-callback': () => setCaptchaToken(null),
          'error-callback': () => setCaptchaToken(null),
        });
      } else if (provider === 'hcaptcha' && w.hcaptcha) {
        captchaWidgetId.current = w.hcaptcha.render(captchaContainerRef.current, {
          sitekey: siteKey,
          callback: (token: string) => setCaptchaToken(token),
          'expired-callback': () => setCaptchaToken(null),
          'error-callback': () => setCaptchaToken(null),
        });
      } else if (provider === 'recaptcha' && w.grecaptcha) {
        // reCAPTCHA v3 — execute immediately, no visible widget
        w.grecaptcha.ready(() => {
          w.grecaptcha.execute(siteKey, { action: 'submit' }).then((token: string) => {
            setCaptchaToken(token);
          });
        });
      }
    };

    // Check if script already loaded
    const w = window as any;
    if (
      (provider === 'turnstile' && w.turnstile) ||
      (provider === 'hcaptcha' && w.hcaptcha) ||
      (provider === 'recaptcha' && w.grecaptcha)
    ) {
      captchaScriptLoaded.current = true;
      renderWidget();
      return;
    }

    // Load script
    const script = document.createElement('script');
    if (provider === 'turnstile') {
      script.src = 'https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';
    } else if (provider === 'hcaptcha') {
      script.src = 'https://js.hcaptcha.com/1/api.js?render=explicit';
    } else if (provider === 'recaptcha') {
      script.src = `https://www.google.com/recaptcha/api.js?render=${siteKey}`;
    }
    script.async = true;
    script.defer = true;
    script.onload = () => {
      captchaScriptLoaded.current = true;
      // Small delay for script initialization
      setTimeout(renderWidget, 100);
    };
    document.head.appendChild(script);

    return () => {
      // Clean up widget on unmount
      if (captchaWidgetId.current !== null) {
        const w = window as any;
        if (provider === 'turnstile' && w.turnstile) {
          w.turnstile.remove(captchaWidgetId.current);
        } else if (provider === 'hcaptcha' && w.hcaptcha) {
          w.hcaptcha.reset(captchaWidgetId.current);
        }
      }
    };
  }, [form.requiresCaptcha, form.captchaProvider, form.captchaSiteKey]);

  const resetCaptcha = () => {
    setCaptchaToken(null);
    if (captchaWidgetId.current !== null) {
      const w = window as any;
      if (form.captchaProvider === 'turnstile' && w.turnstile) {
        w.turnstile.reset(captchaWidgetId.current);
      } else if (form.captchaProvider === 'hcaptcha' && w.hcaptcha) {
        w.hcaptcha.reset(captchaWidgetId.current);
      } else if (form.captchaProvider === 'recaptcha' && w.grecaptcha) {
        w.grecaptcha.execute(form.captchaSiteKey, { action: 'submit' }).then((token: string) => {
          setCaptchaToken(token);
        });
      }
    }
  };

  const styling = { ...defaultStyling, ...form.config?.schema?.styling, ...form.config?.styling };
  const radius = getBorderRadius(styling.borderRadius);
  const btnRadius = getButtonRadius(styling.buttonRadius);
  const fontSize = getFontSize(styling.fontSize);
  const phFontSize = getPlaceholderFontSize(styling.placeholderFontSize);
  const fieldSpacing = getFieldSpacing(styling.fieldSpacing);
  const formPadding = getFormPadding(styling.formPadding);
  const labelSpacing = getLabelSpacing(styling.labelSpacing);
  const formMaxWidth = getFormMaxWidth(styling.formWidth);
  const btnBgColor = styling.primaryColor;
  const btnTextColor = styling.buttonColor;
  // Normalize font family - support legacy single values by adding fallbacks
  // For SDK embedded forms, default to 'inherit' so the form uses the website's font
  const fontFamily = styling.fontFamily 
    ? (styling.fontFamily.includes(',') ? styling.fontFamily : `${styling.fontFamily}, sans-serif`)
    : 'inherit';
  const btnAlign = getButtonAlign(styling.buttonAlign);
  const resolvedButtonText = styling.buttonText || submitText;

  // Google Fonts that need to be loaded
  const googleFonts = ['Inter', 'Roboto', 'Open Sans', 'Lato', 'Poppins', 'Montserrat', 'Nunito', 'Source Sans Pro', 'Raleway', 'Ubuntu', 'Playfair Display', 'Merriweather'];
  const fontToLoad = styling.fontFamily?.split(',')[0]?.trim();
  
  // Check if page already has custom fonts loaded (don't override existing fonts)
  const hasExistingFonts = useMemo(() => {
    if (typeof document === 'undefined') return false;
    const links = document.querySelectorAll('link[rel="stylesheet"]');
    for (const link of links) {
      const href = (link as HTMLLinkElement).href || '';
      if (href.includes('fonts.googleapis.com') || href.includes('fonts.gstatic.com') || href.includes('typekit') || href.includes('fonts.')) {
        return true;
      }
    }
    // Also check for @font-face in existing stylesheets
    try {
      for (const sheet of document.styleSheets) {
        try {
          const rules = sheet.cssRules || sheet.rules;
          if (rules) {
            for (const rule of rules) {
              if (rule instanceof CSSFontFaceRule) {
                return true;
              }
            }
          }
        } catch {
          // Cross-origin stylesheets will throw, ignore
        }
      }
    } catch {
      // Ignore errors
    }
    return false;
  }, []);

  const googleFontUrl = fontToLoad && googleFonts.includes(fontToLoad) && !hasExistingFonts
    ? `https://fonts.googleapis.com/css2?family=${fontToLoad.replace(/ /g, '+')}:wght@400;500;600;700&display=swap`
    : null;

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    const result = await form.submit(captchaToken || undefined);
    if (!result) {
      // Reset captcha on failure
      resetCaptcha();
    }
  };

  const handleChange = (
    e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
      form.setValue(name, (e.target as HTMLInputElement).checked);
    } else if (type === 'file') {
      form.setValue(name, (e.target as HTMLInputElement).files?.[0]);
    } else {
      form.setValue(name, value);
    }
  };

  if (form.isInitializing) {
    return (
      <div
        className={className}
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '2rem',
          ...style,
        }}
      >
        <svg width="24" height="24" viewBox="0 0 24 24" style={{ animation: 'spin 1s linear infinite', color: '#9ca3af' }}>
          <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" fill="none" strokeDasharray="31.4 31.4" strokeLinecap="round"/>
        </svg>
        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    );
  }

  // Show loading spinner if config hasn't loaded yet
  if (!form.config) {
    return (
      <div
        className={className}
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '2rem',
          ...style,
        }}
      >
        <svg width="24" height="24" viewBox="0 0 24 24" style={{ animation: 'spin 1s linear infinite', color: '#9ca3af' }}>
          <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" fill="none" strokeDasharray="31.4 31.4" strokeLinecap="round"/>
        </svg>
        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    );
  }

  if (!form.config.active) {
    return (
      <div
        className={className}
        style={{
          padding: '2rem',
          textAlign: 'center',
          color: '#ef4444',
          ...style,
        }}
      >
        This form is not available
      </div>
    );
  }

  if (form.isSubmitted) {
    return (
      <div
        className={className}
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          minHeight: '100%',
          padding: formPadding,
          textAlign: 'center',
          backgroundColor: styling.transparentBackground ? 'transparent' : styling.backgroundColor,
          color: styling.textColor,
          borderRadius: radius,
          maxWidth: formMaxWidth,
          margin: '0 auto',
          fontFamily,
          ...style,
        }}
      >
        <div>
          <svg
            style={{
              width: '3rem',
              height: '3rem',
              margin: '0 auto 1rem',
              color: styling.successColor || '#22c55e',
            }}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M5 13l4 4L19 7"
            />
          </svg>
          <p style={{ fontSize: '1.125rem', fontWeight: 500 }}>
            {form.config.settings?.successMessage || 'Form submitted successfully!'}
          </p>
          <button
            type="button"
            onClick={form.reset}
            style={{
              marginTop: '1rem',
              background: 'none',
              border: 'none',
              color: styling.primaryColor,
              textDecoration: 'underline',
              cursor: 'pointer',
              fontSize: '0.875rem',
            }}
          >
            Submit again
          </button>
        </div>
      </div>
    );
  }

  const fields = form.config.schema?.fields || [];
  const showBranding = form.config.branding?.enabled !== false;
  const brandingText = form.config.branding?.text || 'Powered by forms.expert';
  const brandingUrl = form.config.branding?.url || 'https://forms.expert';

  const wrapperStyle: CSSProperties = {
    ...(styling.backgroundImageUrl ? {
      backgroundImage: `url(${styling.backgroundImageUrl})`,
      backgroundSize: 'cover',
      backgroundPosition: 'center',
    } : {}),
    position: 'relative' as const,
  };

  const formEl = (
    <form
      onSubmit={handleSubmit}
      className={className}
      data-fe-scope={formScopeId}
      style={{
        fontFamily,
        fontSize,
        backgroundColor: styling.transparentBackground ? 'transparent' : styling.backgroundColor,
        color: styling.textColor,
        padding: formPadding,
        borderRadius: radius,
        maxWidth: formMaxWidth,
        width: '100%',
        margin: '0 auto',
        position: 'relative',
        ...style,
      }}
    >
      {/* Load Google Font if needed */}
      {googleFontUrl && (
        <link rel="stylesheet" href={googleFontUrl} />
      )}
      {/* Scoped placeholder styles */}
      <style dangerouslySetInnerHTML={{ __html: `
        form[data-fe-scope="${formScopeId}"] input::placeholder, form[data-fe-scope="${formScopeId}"] textarea::placeholder { font-size: ${phFontSize};${styling.placeholderColor ? ` color: ${styling.placeholderColor};` : ''} }
        form[data-fe-scope="${formScopeId}"] button[type="submit"]:hover:not(:disabled) { filter: brightness(0.9); }
        form[data-fe-scope="${formScopeId}"] button[type="submit"]:active:not(:disabled) { filter: brightness(0.85); transform: scale(0.98); }
        form[data-fe-scope="${formScopeId}"] a[href]:hover { filter: brightness(0.9); }
        form[data-fe-scope="${formScopeId}"] a[href]:active { filter: brightness(0.85); }
        form[data-fe-scope="${formScopeId}"] input:not([type="checkbox"]):not([type="radio"]):focus,
        form[data-fe-scope="${formScopeId}"] textarea:focus,
        form[data-fe-scope="${formScopeId}"] select:focus {
          outline: none !important;
          border-color: ${styling.primaryColor || '#3b82f6'} !important;
          box-shadow: 0 0 0 2px ${styling.primaryColor || '#3b82f6'}33 !important;
          -webkit-appearance: none;
        }
      ` }} />
      {/* Logo */}
      {styling.logoUrl && (
        <div style={{
          textAlign: styling.logoPosition === 'top-left' ? 'left' : styling.logoPosition === 'top-right' ? 'right' : 'center',
          marginBottom: '1rem',
        }}>
          <img src={styling.logoUrl} alt="" style={{ maxHeight: '48px' }} />
        </div>
      )}

      {/* Cover image */}
      {styling.coverImageUrl && (
        <img
          src={styling.coverImageUrl}
          alt=""
          style={{
            width: '100%',
            maxHeight: '200px',
            objectFit: 'cover',
            borderRadius: `${radius} ${radius} 0 0`,
            marginBottom: '1rem',
          }}
        />
      )}

      {/* Form name */}
      {(form.config.settings?.showFormName !== false) && form.config.name && (
        <div style={{
          fontSize: styling.formNameFontSize != null ? `${styling.formNameFontSize}px` : '1.5rem',
          fontWeight: styling.formNameFontWeight === 'normal' ? 400 : styling.formNameFontWeight === 'medium' ? 500 : styling.formNameFontWeight === 'semibold' ? 600 : 700,
          marginBottom: '0.5rem',
          color: styling.textColor,
        }}>
          {form.config.hostedConfig?.pageTitle || form.config.name}
        </div>
      )}

      {groupFieldsIntoRows(fields).map((group, idx) => {
        if (group.type === 'single') {
          return (
            <FormFieldInput
              key={group.field.name}
              field={group.field}
              value={form.values[group.field.name]}
              error={form.errors[group.field.name]}
              onChange={handleChange}
              onValueChange={(name, val) => form.setValue(name, val)}
              styling={styling}
              fieldSpacing={fieldSpacing}
              labelSpacing={labelSpacing}
              phFontSize={phFontSize}
            />
          );
        }
        return (
          <div key={`row-${idx}`} style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap', marginBottom: fieldSpacing }}>
            {group.fields.map((f) => (
              <div key={f.name} style={{ flex: getWidthPercent(f.width) ? `0 0 calc(${getWidthPercent(f.width)} - 0.75rem)` : '1 1 0', minWidth: '180px' }}>
                <FormFieldInput
                  field={f}
                  value={form.values[f.name]}
                  error={form.errors[f.name]}
                  onChange={handleChange}
                  onValueChange={(name, val) => form.setValue(name, val)}
                  styling={styling}
                  fieldSpacing={'0'}
                  labelSpacing={labelSpacing}
                  phFontSize={phFontSize}
                />
              </div>
            ))}
          </div>
        );
      })}

      {/* Honeypot field — hidden from users, catches bots */}
      {form.honeypotEnabled && (
        <div style={{ position: 'absolute', left: '-9999px', opacity: 0, height: 0, overflow: 'hidden' }} aria-hidden="true">
          <input type="text" name="_hp" tabIndex={-1} autoComplete="off" />
        </div>
      )}

      {/* Captcha widget */}
      {form.requiresCaptcha && form.captchaProvider !== 'recaptcha' && (
        <div ref={captchaContainerRef} style={{ marginTop: '1rem' }} />
      )}

      {(() => {
        const btnSizeMap: Record<string, { px: string; py: string; fs: string }> = {
          small: { px: '0.75rem', py: '0.375rem', fs: '0.875rem' },
          medium: { px: '1.25rem', py: '0.625rem', fs: '1rem' },
          large: { px: '1.75rem', py: '0.875rem', fs: '1.125rem' },
        };
        const btnSize = btnSizeMap[styling.buttonSize || 'medium'];
        const btnPx = styling.buttonPaddingX != null ? `${styling.buttonPaddingX}px` : btnSize.px;
        const btnPy = styling.buttonPaddingY != null ? `${styling.buttonPaddingY}px` : btnSize.py;
        const btnFs = styling.buttonFontSize != null ? `${styling.buttonFontSize}px` : btnSize.fs;
        const btnBg = styling.buttonGradient || (styling.buttonStyle === 'filled' ? btnBgColor : 'transparent');

        const sec = styling.secondaryButton as SecondaryButton | undefined;
        const secColor = sec?.color || btnBgColor;
        const secStyle: CSSProperties | undefined = sec?.enabled ? {
          display: 'inline-flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: `${btnPy} ${btnPx}`,
          fontWeight: 500,
          fontSize: sec.fontSize != null ? `${sec.fontSize}px` : btnFs,
          fontFamily: 'inherit',
          borderRadius: btnRadius,
          cursor: 'pointer',
          textDecoration: sec.style === 'link' ? 'underline' : 'none',
          background: sec.style === 'filled' ? secColor : 'transparent',
          color: sec.textColor || (sec.style === 'filled' ? '#ffffff' : secColor),
          border: sec.style === 'outlined' ? `2px solid ${secColor}` : 'none',
          marginTop: sec.marginTop != null ? `${sec.marginTop}px` : undefined,
          marginBottom: sec.marginBottom != null ? `${sec.marginBottom}px` : undefined,
          maxWidth: '100%',
          boxSizing: 'border-box' as const,
          flexShrink: 1,
          minWidth: 0,
          whiteSpace: 'nowrap' as const,
          overflow: 'hidden',
          textOverflow: 'ellipsis',
        } : undefined;

        return (
          <>
            <div style={{ display: 'flex', justifyContent: btnAlign, marginTop: '1rem', gap: '0.5rem', flexWrap: 'wrap' }}>
              {sec?.enabled && secStyle && sec.position === 'left' && (
                <a href={sec.href || '#'} target={sec.openInNewTab ? '_blank' : undefined} rel={sec.openInNewTab ? 'noopener noreferrer' : undefined} style={{ ...secStyle, display: 'inline-flex', alignItems: 'center', gap: '0.5rem' }}>
                  {sec.icon && sec.iconPosition !== 'right' && <span style={{ display: 'inline-flex', flexShrink: 0 }} dangerouslySetInnerHTML={{ __html: sec.icon }} />}
                  <span>{sec.text || 'Learn More'}</span>
                  {sec.icon && sec.iconPosition === 'right' && <span style={{ display: 'inline-flex', flexShrink: 0 }} dangerouslySetInnerHTML={{ __html: sec.icon }} />}
                </a>
              )}
              <button
                type="submit"
                disabled={form.isLoading}
                className={styling.buttonClassName}
                style={{
                  ...(styling.buttonFullWidth ? { width: '100%' } : (styling.buttonAlign ? {} : { width: '100%' })),
                  padding: `${btnPy} ${btnPx}`,
                  fontWeight: 500,
                  fontSize: btnFs,
                  fontFamily: 'inherit',
                  borderRadius: btnRadius,
                  cursor: form.isLoading ? 'not-allowed' : 'pointer',
                  opacity: form.isLoading ? 0.5 : 1,
                  background: btnBg,
                  color:
                    styling.buttonStyle === 'filled'
                      ? (btnTextColor || 'white')
                      : btnBgColor,
                  border:
                    styling.buttonStyle === 'filled'
                      ? 'none'
                      : `2px solid ${btnBgColor}`,
                  maxWidth: '100%',
                  boxSizing: 'border-box',
                  flexShrink: 1,
                  minWidth: 0,
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '0.5rem',
                }}
              >
                {!form.isLoading && styling.buttonIcon && styling.buttonIconPosition !== 'right' && (
                  <span style={{ display: 'inline-flex', flexShrink: 0 }} dangerouslySetInnerHTML={{ __html: styling.buttonIcon }} />
                )}
                <span>{form.isLoading ? 'Submitting...' : resolvedButtonText}</span>
                {!form.isLoading && styling.buttonIcon && styling.buttonIconPosition === 'right' && (
                  <span style={{ display: 'inline-flex', flexShrink: 0 }} dangerouslySetInnerHTML={{ __html: styling.buttonIcon }} />
                )}
              </button>
              {sec?.enabled && secStyle && sec.position !== 'left' && sec.position !== 'below' && (
                <a href={sec.href || '#'} target={sec.openInNewTab ? '_blank' : undefined} rel={sec.openInNewTab ? 'noopener noreferrer' : undefined} style={{ ...secStyle, display: 'inline-flex', alignItems: 'center', gap: '0.5rem', marginLeft: 'auto' }}>
                  {sec.icon && sec.iconPosition !== 'right' && <span style={{ display: 'inline-flex', flexShrink: 0 }} dangerouslySetInnerHTML={{ __html: sec.icon }} />}
                  <span>{sec.text || 'Learn More'}</span>
                  {sec.icon && sec.iconPosition === 'right' && <span style={{ display: 'inline-flex', flexShrink: 0 }} dangerouslySetInnerHTML={{ __html: sec.icon }} />}
                </a>
              )}
            </div>
            {sec?.enabled && secStyle && sec.position === 'below' && (
              <div style={{
                display: 'flex',
                justifyContent: sec.align === 'center' ? 'center' : sec.align === 'right' ? 'flex-end' : sec.align === 'left' ? 'flex-start' : btnAlign,
                marginTop: sec.marginTop != null ? `${sec.marginTop}px` : '0.5rem',
                marginBottom: sec.marginBottom != null ? `${sec.marginBottom}px` : undefined,
              }}>
                <a href={sec.href || '#'} target={sec.openInNewTab ? '_blank' : undefined} rel={sec.openInNewTab ? 'noopener noreferrer' : undefined} style={{ ...secStyle, display: 'inline-flex', alignItems: 'center', gap: '0.5rem', marginTop: 0, marginBottom: 0 }}>
                  {sec.icon && sec.iconPosition !== 'right' && <span style={{ display: 'inline-flex', flexShrink: 0 }} dangerouslySetInnerHTML={{ __html: sec.icon }} />}
                  <span>{sec.text || 'Learn More'}</span>
                  {sec.icon && sec.iconPosition === 'right' && <span style={{ display: 'inline-flex', flexShrink: 0 }} dangerouslySetInnerHTML={{ __html: sec.icon }} />}
                </a>
              </div>
            )}
          </>
        );
      })()}

      {showBranding && (
        <div
          style={{
            textAlign: 'center',
            marginTop: '1rem',
            paddingTop: '0.75rem',
            borderTop: `1px solid ${styling.theme === 'dark' ? '#374151' : '#e5e7eb'}`,
          }}
        >
          <a
            href={brandingUrl}
            target="_blank"
            rel="noopener noreferrer"
            style={{
              color: styling.theme === 'dark' ? '#9ca3af' : '#6b7280',
              textDecoration: 'none',
              fontSize: '0.75rem',
            }}
          >
            {brandingText}
          </a>
        </div>
      )}
    </form>
  );

  if (styling.backgroundImageUrl) {
    return (
      <div style={wrapperStyle}>
        {styling.backgroundOverlay ? (
          <div style={{
            position: 'absolute',
            inset: 0,
            backgroundColor: `rgba(0,0,0,${styling.backgroundOverlay})`,
            pointerEvents: 'none',
          }} />
        ) : null}
        {formEl}
      </div>
    );
  }

  return formEl;
}

interface FormFieldInputProps {
  field: FormField;
  value: unknown;
  error?: string;
  onChange: (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => void;
  onValueChange: (name: string, value: unknown) => void;
  styling: FormStyling;
  fieldSpacing: string;
  labelSpacing: string;
  phFontSize: string;
}

function FormFieldInput({
  field,
  value,
  error,
  onChange,
  onValueChange,
  styling,
  fieldSpacing,
  labelSpacing,
  phFontSize,
}: FormFieldInputProps) {
  const radius = getBorderRadius(styling.borderRadius);
  const fieldRadius = getFieldBorderRadius(styling.fieldBorderRadius);
  const fontSize = getFontSize(styling.fontSize);
  const isInline = styling.labelPosition === 'left' || styling.fieldLayout === 'inline';

  const isBottomBorder = styling.fieldBorderStyle === 'bottom';
  const fieldPadding = styling.fieldPaddingX != null || styling.fieldPaddingY != null
    ? `${styling.fieldPaddingY ?? 8}px ${styling.fieldPaddingX ?? 12}px`
    : '0.5rem 0.75rem';

  const inputStyle: CSSProperties = {
    width: '100%',
    padding: fieldPadding,
    border: isBottomBorder ? 'none' : `1px solid ${error ? '#ef4444' : styling.theme === 'dark' ? '#4b5563' : '#d1d5db'}`,
    ...(isBottomBorder ? { borderBottom: `1px solid ${error ? '#ef4444' : styling.theme === 'dark' ? '#4b5563' : '#d1d5db'}` } : {}),
    borderRadius: isBottomBorder ? 0 : fieldRadius,
    fontSize,
    fontFamily: 'inherit',
    backgroundColor: styling.inputBackgroundColor || (styling.theme === 'dark' ? '#374151' : '#ffffff'),
    color: styling.textColor,
  };

  const getOpts = (): { value: string; label: string; imageUrl?: string }[] => {
    if (!field.options) return [];
    return field.options.map((o) => typeof o === 'string' ? { value: o, label: o } : o);
  };

  // Layout fields (no data)
  if (field.type === 'heading') {
    return (
      <div style={{ marginBottom: fieldSpacing }}>
        <h2 style={{ fontSize: getHeadingSize(styling.headingSize), fontWeight: 600 }}>{field.label}</h2>
        {field.content && (
          <p style={{ fontSize: '0.875rem', color: styling.theme === 'dark' ? '#9ca3af' : '#6b7280', marginTop: '0.25rem' }}>{field.content}</p>
        )}
      </div>
    );
  }
  if (field.type === 'divider') {
    return <hr style={{ marginBottom: fieldSpacing, border: 'none', borderTop: `1px solid ${styling.theme === 'dark' ? '#4b5563' : '#d1d5db'}` }} />;
  }
  if (field.type === 'paragraph') {
    const pSize = field.paragraphFontSize ? `${field.paragraphFontSize}px` : getParagraphSize(styling.paragraphSize);
    return (
      <div style={{ marginBottom: fieldSpacing }}>
        {field.label && (
          <p style={{ fontWeight: 500, fontSize: pSize, marginBottom: '0.25rem' }}>{field.label}</p>
        )}
        {field.content && (
          <div
            style={{ fontSize: pSize, color: styling.theme === 'dark' ? '#9ca3af' : '#6b7280' }}
            dangerouslySetInnerHTML={{ __html: field.content }}
          />
        )}
      </div>
    );
  }
  if (field.type === 'hidden') {
    return <input type="hidden" name={field.name} value={String(value || field.defaultValue || '')} />;
  }

  // Checkbox / toggle / consent — inline layout
  if (field.type === 'checkbox' || field.type === 'toggle' || field.type === 'consent') {
    const consentSize = field.type === 'consent' && field.consentFontSize ? `${field.consentFontSize}px` : undefined;
    return (
      <div style={{ display: 'flex', alignItems: 'flex-start', gap: '0.5rem', marginBottom: fieldSpacing }}>
        <input
          type="checkbox"
          id={field.name}
          name={field.name}
          checked={Boolean(value)}
          onChange={onChange}
          required={field.required}
          style={{ width: '1rem', height: '1rem', accentColor: styling.primaryColor, marginTop: '0.125rem', flexShrink: 0, backgroundColor: 'transparent' }}
        />
        <div>
          {(field.label || (field.type === 'consent' && field.consentText)) && (
            <label htmlFor={field.name} className={styling.labelClassName} style={{ cursor: 'pointer', ...(consentSize ? { fontSize: consentSize } : {}) }}>
              {field.type === 'consent' && field.consentText
                ? field.consentText
                : field.label}
              {field.required && !styling.hideRequiredAsterisk && <span style={{ color: '#ef4444', marginLeft: '0.25rem' }}>*</span>}
            </label>
          )}
          {field.type === 'consent' && field.consentUrl && (
            <a href={field.consentUrl} target="_blank" rel="noopener noreferrer" style={{ color: styling.primaryColor, fontSize: '0.75rem', marginTop: '0.125rem', display: 'inline-block' }}>View policy</a>
          )}
          {error && <div style={{ color: styling.errorColor || '#ef4444', fontSize: '0.875rem', marginTop: '0.25rem' }}>{error}</div>}
        </div>
      </div>
    );
  }

  const labelEl = field.label ? (
    <label
      htmlFor={field.name}
      className={styling.labelClassName}
      style={{
        display: 'block',
        fontWeight: 500,
        ...(isInline
          ? { width: '33%', flexShrink: 0, paddingTop: '0.5rem', marginBottom: 0 }
          : { marginBottom: labelSpacing }),
      }}
    >
      {field.label}
      {field.required && !styling.hideRequiredAsterisk && <span style={{ color: '#ef4444', marginLeft: '0.25rem' }}>*</span>}
    </label>
  ) : null;

  const errorEl = error ? (
    <div style={{ color: styling.errorColor || '#ef4444', fontSize: '0.875rem', marginTop: '0.25rem' }}>{error}</div>
  ) : null;

  let fieldEl: JSX.Element;

  if (field.type === 'textarea' || field.type === 'richText') {
    fieldEl = (
      <textarea
        id={field.name}
        name={field.name}
        value={String(value || '')}
        onChange={onChange}
        placeholder={field.placeholder}
        required={field.required}
        style={{ ...inputStyle, minHeight: '100px', resize: 'vertical' }}
        className={styling.fieldClassName}
      />
    );
  } else if (field.type === 'select' || field.type === 'dropdown') {
    fieldEl = (
      <select id={field.name} name={field.name} value={String(value || '')} onChange={onChange} required={field.required} style={inputStyle} className={styling.fieldClassName}>
        <option value="">Select an option...</option>
        {getOpts().map((opt) => <option key={opt.value} value={opt.value}>{opt.label}</option>)}
      </select>
    );
  } else if (field.type === 'radio') {
    fieldEl = (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
        {getOpts().map((opt) => (
          <label key={opt.value} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer' }}>
            <input
              type="radio"
              name={field.name}
              value={opt.value}
              checked={(value as string) === opt.value}
              onChange={() => onValueChange(field.name, opt.value)}
              style={{ accentColor: styling.primaryColor }}
            />
            {opt.label}
          </label>
        ))}
      </div>
    );
  } else if (field.type === 'multiselect') {
    const selected = Array.isArray(value) ? (value as string[]) : [];
    fieldEl = (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
        {getOpts().map((opt) => (
          <label key={opt.value} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer' }}>
            <input
              type="checkbox"
              checked={selected.includes(opt.value)}
              onChange={() => {
                const next = selected.includes(opt.value)
                  ? selected.filter((v) => v !== opt.value)
                  : [...selected, opt.value];
                onValueChange(field.name, next);
              }}
              style={{ accentColor: styling.primaryColor }}
            />
            {opt.label}
          </label>
        ))}
      </div>
    );
  } else if (field.type === 'rating') {
    const max = field.ratingMax || 5;
    const current = Number(value) || 0;
    fieldEl = (
      <div style={{ display: 'flex', gap: '0.25rem' }}>
        {Array.from({ length: max }, (_, i) => i + 1).map((n) => (
          <button
            key={n}
            type="button"
            onClick={() => onValueChange(field.name, n)}
            style={{
              width: '2rem', height: '2rem', cursor: 'pointer', border: 'none',
              background: 'none', padding: 0, fontSize: '1.5rem',
              color: n <= current ? '#f59e0b' : (styling.theme === 'dark' ? '#4b5563' : '#d1d5db'),
              transition: 'color 0.15s',
            }}
          >★</button>
        ))}
      </div>
    );
  } else if (field.type === 'scale' || field.type === 'opinionScale') {
    const min = field.min ?? 1;
    const max = field.max ?? 10;
    const current = value as number | undefined;
    fieldEl = (
      <div>
        <div style={{ display: 'flex', gap: '0.25rem', flexWrap: 'wrap' }}>
          {Array.from({ length: max - min + 1 }, (_, i) => min + i).map((n) => (
            <button
              key={n}
              type="button"
              onClick={() => onValueChange(field.name, n)}
              style={{
                minWidth: '2.25rem', height: '2.25rem', borderRadius: radius, cursor: 'pointer',
                border: `1px solid ${styling.theme === 'dark' ? '#4b5563' : '#d1d5db'}`,
                background: current === n ? styling.primaryColor : (styling.theme === 'dark' ? '#374151' : '#ffffff'),
                color: current === n ? 'white' : styling.textColor,
                fontSize: '0.875rem', transition: 'all 0.15s',
              }}
            >{n}</button>
          ))}
        </div>
        {(field.lowLabel || field.highLabel) && (
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.75rem', color: styling.theme === 'dark' ? '#9ca3af' : '#6b7280', marginTop: '0.25rem' }}>
            <span>{field.lowLabel}</span>
            <span>{field.highLabel}</span>
          </div>
        )}
      </div>
    );
  } else if (field.type === 'slider') {
    const min = field.min ?? 0;
    const max = field.max ?? 100;
    const step = field.step ?? 1;
    fieldEl = (
      <div>
        <input
          type="range"
          id={field.name}
          name={field.name}
          min={min}
          max={max}
          step={step}
          value={Number(value) || min}
          onChange={(e) => onValueChange(field.name, Number(e.target.value))}
          style={{ width: '100%', accentColor: styling.primaryColor }}
        />
        <div style={{ textAlign: 'center', fontSize: '0.875rem', marginTop: '0.25rem' }}>{String(value ?? min)}</div>
      </div>
    );
  } else if (field.type === 'imageChoice') {
    const selected = value as string | undefined;
    fieldEl = (
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
        {getOpts().map((opt) => (
          <button
            key={opt.value}
            type="button"
            onClick={() => onValueChange(field.name, opt.value)}
            style={{
              border: `2px solid ${selected === opt.value ? styling.primaryColor : (styling.theme === 'dark' ? '#4b5563' : '#d1d5db')}`,
              borderRadius: radius, padding: '0.5rem', cursor: 'pointer', textAlign: 'center',
              background: 'none', transition: 'border-color 0.15s',
            }}
          >
            {opt.imageUrl && <img src={opt.imageUrl} alt={opt.label} style={{ maxWidth: '80px', maxHeight: '80px', objectFit: 'cover', borderRadius: radius }} />}
            <div style={{ fontSize: '0.875rem', marginTop: '0.25rem' }}>{opt.label}</div>
          </button>
        ))}
      </div>
    );
  } else if (field.type === 'file') {
    fieldEl = (
      <input
        type="file"
        id={field.name}
        name={field.name}
        onChange={onChange}
        required={field.required}
        accept={field.allowedMimeTypes?.join(',')}
        multiple={field.multiple}
        style={inputStyle}
        className={styling.fieldClassName}
      />
    );
  } else if (field.type === 'name') {
    const nameVal = (value || {}) as Record<string, string>;
    const nameFields = field.nameFields || ['first', 'last'];
    const labels: Record<string, string> = { prefix: 'Prefix', first: 'First Name', middle: 'Middle', last: 'Last Name', suffix: 'Suffix' };
    fieldEl = (
      <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
        {nameFields.map((nf) => (
          <input
            key={nf}
            placeholder={labels[nf] || nf}
            value={nameVal[nf] || ''}
            onChange={(e) => onValueChange(field.name, { ...nameVal, [nf]: e.target.value })}
            style={{ ...inputStyle, flex: 1, minWidth: '120px' }}
            className={styling.fieldClassName}
          />
        ))}
      </div>
    );
  } else if (field.type === 'address') {
    const addr = (value || {}) as Record<string, string>;
    const addrFields = field.addressFields || ['street', 'city', 'state', 'zip', 'country'];
    const labels: Record<string, string> = { street: 'Street', street2: 'Street 2', city: 'City', state: 'State', zip: 'ZIP', country: 'Country' };
    fieldEl = (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
        {addrFields.map((af) => (
          <input
            key={af}
            placeholder={labels[af] || af}
            value={addr[af] || ''}
            onChange={(e) => onValueChange(field.name, { ...addr, [af]: e.target.value })}
            style={inputStyle}
            className={styling.fieldClassName}
          />
        ))}
      </div>
    );
  } else if (field.type === 'currency') {
    fieldEl = (
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
        {field.currencySymbol && <span>{field.currencySymbol}</span>}
        <input
          type="number"
          id={field.name}
          name={field.name}
          value={String(value || '')}
          onChange={onChange}
          step={0.01}
          min={field.min}
          max={field.max}
          required={field.required}
          style={inputStyle}
          className={styling.fieldClassName}
        />
      </div>
    );
  } else if (field.type === 'colorPicker') {
    fieldEl = (
      <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
        <input
          type="color"
          id={field.name}
          value={String(value || '#000000')}
          onChange={(e) => onValueChange(field.name, e.target.value)}
          style={{ width: '3rem', height: '2.25rem', border: 'none', cursor: 'pointer', padding: 0 }}
        />
        <input
          type="text"
          value={String(value || '')}
          onChange={(e) => onValueChange(field.name, e.target.value)}
          placeholder="#000000"
          style={{ ...inputStyle, flex: 1 }}
          className={styling.fieldClassName}
        />
      </div>
    );
  } else if (field.type === 'dateRange') {
    const range = (value || {}) as { start?: string; end?: string };
    fieldEl = (
      <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
        <input type="date" value={range.start || ''} onChange={(e) => onValueChange(field.name, { ...range, start: e.target.value })} style={{ ...inputStyle, flex: 1 }} className={styling.fieldClassName} />
        <span>to</span>
        <input type="date" value={range.end || ''} onChange={(e) => onValueChange(field.name, { ...range, end: e.target.value })} style={{ ...inputStyle, flex: 1 }} className={styling.fieldClassName} />
      </div>
    );
  } else {
    // Default: text, email, number, date, phone, url, password, time, datetime, etc.
    const typeMap: Record<string, string> = {
      phone: 'tel', url: 'url', datetime: 'datetime-local', time: 'time', date: 'date',
      number: 'number', email: 'email', password: 'password',
    };
    fieldEl = (
      <input
        type={typeMap[field.type] || 'text'}
        id={field.name}
        name={field.name}
        value={String(value || '')}
        onChange={onChange}
        placeholder={field.placeholder}
        required={field.required}
        min={field.min}
        max={field.max}
        step={field.step}
        maxLength={field.maxLength}
        style={inputStyle}
        className={styling.fieldClassName}
      />
    );
  }

  return (
    <div
      style={{
        marginBottom: fieldSpacing,
        ...(isInline ? { display: 'flex', alignItems: 'flex-start', gap: '1rem' } : {}),
      }}
    >
      {labelEl}
      <div style={isInline ? { flex: 1 } : {}}>
        {fieldEl}
        {errorEl}
      </div>
    </div>
  );
}
